<?php

    use Service\Service\Place\PlaceSortingStrategy;

    class ListPlacesHandler extends Handler {
        public function handle($input) {
            global $placeService;

            $type = isset($input["type"]) ? $input["type"] : "regular";
            unset($input["type"]);
            
            $sortingStrategy = PlaceSortingStrategy::Default;            
            if (isset($input["sort"])) {
                if ($input["sort"] === "score") {
                    $sortingStrategy = PlaceSortingStrategy::ScoreDescending;
                }
                if ($input["sort"] === "quality") {
                    $sortingStrategy = PlaceSortingStrategy::QualityAscending;
                }
            }
            unset($input["sort"]);

            $response = array();    
            if ($type == "regular") {
                $response = $placeService->getRegularPlaces(isset($input["categoryId"]) ? $input["categoryId"] : NULL,
                    isset($input["labelId"]) ? $input["labelId"] : NULL,
                    isset($input["tripId"]) ? $input["tripId"] : NULL,
                    isset($input["year"]) ? $input["year"] : NULL,
                    isset($input["albumId"]) ? $input["albumId"] : NULL,
                    isset($input["maxQuality"]) ? $input["maxQuality"] : NULL,
                    isset($input["minStart"]) ? $input["minStart"] : NULL,
                    isset($input["maxEnd"]) ? $input["maxEnd"] : NULL,
                    isset($input["include"]) ? explode(",", $input["include"]) : array(),
                    $sortingStrategy);
            }
            else if ($type == "candidate") { 
                $response = $placeService->getCandidatePlaces(isset($input["categoryId"]) ? $input["categoryId"] : NULL,
                    isset($input["tripId"]) ? $input["tripId"] : NULL,
                    isset($input["labelId"]) ? $input["labelId"] : NULL,
                    isset($input["include"]) ? explode(",", $input["include"]) : array());
            }

            return $this->createResponse(200, $response);
        }

        public function getRequiredRole() {
            return "USER";
        }
        
        public function isProtected() {
            return TRUE;
        }

        public function getTag() {
            return "Places";
        }

        public function getPath() {
            return "/places";
        }

        public function getParameters() {
            return array(
                $this->createQueryParameter("year", "integer", 2024),
                $this->createQueryParameter("tripId", "integer", 128),
                $this->createQueryParameter("labelId", "integer", 2),
                $this->createQueryParameter("categoryId", "integer", 2),
                $this->createQueryParameter("albumId", "integer", 2),
                $this->createQueryParameter("minStart", "integer", 1716154060),
                $this->createQueryParameter("maxEnd", "integer", 1716154060),
                $this->createQueryParameter("type", "string", array("regular", "candidate")),
                $this->createQueryParameter("include", "string", "EXCERPT,CATEGORIES,HIGHLIGHTS,DATES"));
        }

        public function getMethod() {
            return "GET";
        }
        
        public function getShortDescription() {
            return "Retrieve a collection of places";
        }
        
        public function getLongDescription() {
            return "Retrieves a collection of places matching the specified filters. If the `type` filter is not specified, the value `regular` will be used as a default. For a retrieval of proposed dates for a trip candidate, it is necessary to specify the `tripId` filter. If not specified, the `dates` array is always empty for candidate places. Some fields in the result may be omitted due to performance reasons, these can be enabled by various include filters.";
        }
        
        public function getRequestExamples() {
            return array();
        }

        public function getResponseExamples() {
            return array(
                $this->createResponseExample("Regular places", 200, '[{"id":5022,"name":"Mohuč","country":"Německo","latitude":49.9928617,"longitude":8.2472526,"timezone":"Europe/Berlin","mainHighlight":{"id":715,"url":{"thumbnail":"https://lriedel.cz/cache/highlight/thumbnail/AGhjs2mxj_kxpHXFPCVXA5mXiAgPcWbPeszMDNS3Qk6hsefhzuoFi-TQJ_O2CQBXRZxW-WuJYU44cs1bXJrxERgT1cJ-nfzrHA.jpg","full":null},"focalLength":19,"aperture":10,"shutterSpeed":0.009999999,"iso":100,"timestamp":1651762919},"excerpt":"Mohuč, s klidným duchem se vznáší nad mohutným Rýnem, je místem, kde se historie spojuje s moderní elegancí. Projděte se malebnými uličkami starého města, s romantickými dřevěnými domky, a užijte si atmosféru dávných dob. Zažijte klid u katedrály sv. Štěpána, jejíž věže shlížejí na město s majestátností a elegancí. Mohuč, město vinařů, se pyšní bohatou vinnou kulturou a svými vinicemi rozprostřenými po okolních kopcích. Vychutnejte si bohatý výběr zdejších vín a zažijte atmosféru vinných sklepů a festivalů, kde se život v Mohuči potkává s tradičními zvyky. Projděte se po břehu Rýna, kde se otevírá panoramatický výhled na historické centrum, a nechte se unést jeho majestátností. Prozkoumejte muzeum římské říše, které vypráví příběh o historii tohoto mohutného města. Projděte se po malebných uličních trzích a ochutnejte místní pochoutky a specialit, které vám zanechávají příjemné dojmy.  Mohuč, místo s bohatou historií, živou kulturou a malebnou atmosférou, nabízí nezapomenutelný zážitek pro každého cestovatele.","categories":[{"id":1,"name":"Evropa","category":"CONTINENT","mainHighlight":{"id":1112,"url":{"thumbnail":"https://lriedel.cz/cache/highlight/thumbnail/AGhjs2na-meUTmaaxg9IzCVtf17752sLzJ4HFTUHDoF6MklxTdfcsKn7ayrAYChg9NY9sa2WPA-eiqfg5VYziAT1MiIXEgF3ww.jpg","full":null},"focalLength":18,"aperture":11,"shutterSpeed":0.008,"iso":100,"timestamp":1662109707}},{"id":9,"name":"Evropská unie","category":"REGION","mainHighlight":{"id":1112,"url":{"thumbnail":"https://lriedel.cz/c